const tok = input.trim().split(/\s+/);
let pos = 0;
const nextInt = () => parseInt(tok[pos++], 10);
const r = nextInt(), c = nextInt();
const m = [];
for (let i = 0; i < r; i++) {
  const row = [];
  for (let j = 0; j < c; j++) row.push(nextInt());
  m.push(row);
}
let top = 0, bottom = r - 1, left = 0, right = c - 1;
const out = [];
while (top <= bottom && left <= right) {
  for (let j = left; j <= right; j++) out.push(m[top][j]);
  top++;
  for (let i = top; i <= bottom; i++) out.push(m[i][right]);
  right--;
  if (top <= bottom) {
    for (let j = right; j >= left; j--) out.push(m[bottom][j]);
    bottom--;
  }
  if (left <= right) {
    for (let i = bottom; i >= top; i--) out.push(m[i][left]);
    left++;
  }
}
